import{_ as u,a0 as i,w as r,s as a,ao as p,I as n,a1 as s,A as l,x as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180831 How to Create a Slideshow of Photos in Ubuntu 18.04 and other Linux Distributions","title":"如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片","tag":"201809","desc":""},"relativePath":"201809/20180831 How to Create a Slideshow of Photos in Ubuntu 18.04 and other Linux Distributions.md","filePath":"[post].md"}'),d={name:"201809/20180831 How to Create a Slideshow of Photos in Ubuntu 18.04 and other Linux Distributions.md"};function h(b,t,f,m,w,x){const e=i("Link");return r(),a("div",null,[t[19]||(t[19]=p('<h1 id="如何在-ubuntu-和其他-linux-发行版中创建照片幻灯片" tabindex="-1">如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片 <a class="header-anchor" href="#如何在-ubuntu-和其他-linux-发行版中创建照片幻灯片" aria-label="Permalink to “如何在 Ubuntu 和其他 Linux 发行版中创建照片幻灯片”">​</a></h1><p>创建照片幻灯片只需点击几下。以下是如何在 Ubuntu 18.04 和其他 Linux 发行版中制作照片幻灯片。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/Create-photos-Slideshow-Linux.png" alt="How to create slideshow of photos in Ubuntu Linux"></p><p>想象一下，你的朋友和亲戚正在拜访你，并请你展示最近的活动/旅行照片。</p><p>你将照片保存在计算机上，并整齐地放在单独的文件夹中。你邀请计算机附近的所有人。你进入该文件夹​​，单击其中一张图片，然后按箭头键逐个显示照片。</p><p>但那太累了！如果这些图片每隔几秒自动更改一次，那将会好很多。</p><p>这称之为幻灯片，我将向你展示如何在 Ubuntu 中创建照片幻灯片。这能让你在文件夹中循环播放图片并以全屏模式显示它们。</p><h3 id="在-ubuntu-18-04-和其他-linux-发行版中创建照片幻灯片" tabindex="-1">在 Ubuntu 18.04 和其他 Linux 发行版中创建照片幻灯片 <a class="header-anchor" href="#在-ubuntu-18-04-和其他-linux-发行版中创建照片幻灯片" aria-label="Permalink to “在 Ubuntu 18.04 和其他 Linux 发行版中创建照片幻灯片”">​</a></h3><p>虽然有几种图像浏览器可以做到，但我将向你展示大多数发行版中应该提供的两种最常用的工具。</p><h4 id="方法-1-使用-gnome-默认图像浏览器浏览照片幻灯片" tabindex="-1">方法 1：使用 GNOME 默认图像浏览器浏览照片幻灯片 <a class="header-anchor" href="#方法-1-使用-gnome-默认图像浏览器浏览照片幻灯片" aria-label="Permalink to “方法 1：使用 GNOME 默认图像浏览器浏览照片幻灯片”">​</a></h4><p>如果你在 Ubuntu 18.04 或任何其他发行版中使用 GNOME，那么你很幸运。Gnome 的默认图像浏览器，Eye of GNOME，能够在当前文件夹中显示图片的幻灯片。</p><p>只需单击其中一张图片，你将在程序的右上角菜单中看到设置选项。它看起来像堆叠在一起的三条横栏。</p><p>你会在这里看到几个选项。勾选幻灯片选项，它将全屏显示图像。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/create-slideshow-photos-ubuntu-gnome.jpeg" alt="How to create slideshow of photos in Ubuntu Linux"></p><p>默认情况下，图像以 5 秒的间隔变化。你可以进入 “Preferences -&gt; Slideshow” 来更改幻灯片放映间隔。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/change-slideshow-interval-gnome-image.jpeg" alt="change slideshow interval in Ubuntu"></p><h4 id="方法-2-使用-shotwell-photo-manager-进行照片幻灯片放映" tabindex="-1">方法 2：使用 Shotwell Photo Manager 进行照片幻灯片放映 <a class="header-anchor" href="#方法-2-使用-shotwell-photo-manager-进行照片幻灯片放映" aria-label="Permalink to “方法 2：使用 Shotwell Photo Manager 进行照片幻灯片放映”">​</a></h4>',17)),n("p",null,[s(e,{href:"https://wiki.gnome.org/Apps/Shotwell"},{default:l(()=>[...t[0]||(t[0]=[o("Shotwell",-1)])]),_:1}),t[2]||(t[2]=o(" 是一款流行的 ",-1)),s(e,{href:"https://itsfoss.com/linux-photo-management-software/"},{default:l(()=>[...t[1]||(t[1]=[o("Linux 照片管理程序",-1)])]),_:1}),t[3]||(t[3]=o("。适用于所有主要的 Linux 发行版。",-1))]),t[20]||(t[20]=n("p",null,"如果尚未安装，请在你的发行版软件中心中搜索 Shotwell 并安装。",-1)),t[21]||(t[21]=n("p",null,"Shotwell 的运行略有不同。如果你在 Shotwell Viewer 中直接打开照片，则不会看到首选项或者幻灯片的选项。",-1)),t[22]||(t[22]=n("p",null,"对于幻灯片放映和其他选项，你必须打开 Shotwell 并导入包含这些图片的文件夹。导入文件夹后，从左侧窗格中选择该文件夹，然后单击菜单中的 “View”。你应该在此处看到幻灯片选项。只需单击它即可创建所选文件夹中所有图像的幻灯片。",-1)),t[23]||(t[23]=n("p",null,[n("img",{src:"https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/08/create-slideshow-photos-shotwell.jpeg",alt:"How to create slideshow of photos in Ubuntu Linux"})],-1)),t[24]||(t[24]=n("p",null,"你还可以更改幻灯片设置。当图像以全屏显示时，将显示此选项。只需将鼠标悬停在底部，你就会看到一个设置选项。",-1)),t[25]||(t[25]=n("h4",{id:"创建照片幻灯片很容易",tabindex:"-1"},[o("创建照片幻灯片很容易 "),n("a",{class:"header-anchor",href:"#创建照片幻灯片很容易","aria-label":"Permalink to “创建照片幻灯片很容易”"},"​")],-1)),t[26]||(t[26]=n("p",null,"如你所见，在 Linux 中创建照片幻灯片非常简单。我希望你觉得这个简单的提示有用。如果你有任何问题或建议，请在下面的评论栏告诉我们。",-1)),t[27]||(t[27]=n("hr",null,null,-1)),n("p",null,[t[5]||(t[5]=o("via: ",-1)),s(e,{href:"https://itsfoss.com/photo-slideshow-ubuntu/"},{default:l(()=>[...t[4]||(t[4]=[o("https://itsfoss.com/photo-slideshow-ubuntu/",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=o("作者：",-1)),s(e,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...t[6]||(t[6]=[o("Abhishek Prakash",-1)])]),_:1}),t[11]||(t[11]=o(" 选题：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[7]||(t[7]=[o("lujun9972",-1)])]),_:1}),t[12]||(t[12]=o(" 译者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:l(()=>[...t[8]||(t[8]=[o("geekpi",-1)])]),_:1}),t[13]||(t[13]=o(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[14]||(t[14]=[o("LCTT",-1)])]),_:1}),t[17]||(t[17]=o(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:l(()=>[...t[15]||(t[15]=[o("Linux中国",-1)])]),_:1}),t[18]||(t[18]=o(" 荣誉推出",-1))])])}const C=u(d,[["render",h]]);export{T as __pageData,C as default};
